import { useErrorContextValue, useGet, useLoaderContextValue, usePost, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, DatePicker, Form, Input, message, Row, Select, Spin } from 'antd'
import moment from 'moment-timezone'
import { useCallback, useEffect } from 'react'
import { useHistory } from 'react-router'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import FileUploadOnGcsV2 from '../../../../../../components/FileUploadOnGcsV2'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { horizontalLayout, tailFormItemLayout } from '../../../utils/formLayout'
import { AntdUploadFullWidthStyled } from '../../AddNewCase/containers/components/styles'
import { addEditBroadcastApis, apiUrls, PUBLISH_NOW, SAVE_DRAFT, SCHEDULE_PUBLISH, UPDATE_AND_PUBLISH, UPDATE_AND_SCHEDULE, UPDATE_DRAFT } from '../apiConfig'
import { CONTENT, IMAGE, PUBLISH_DATE, RECIPIENTS, TITLE } from './constants'
import { AddBroadcastCenterStyleWrapper } from './index.style'
import { formatToBeSentValues, getNextMinute, getPreviousMinutes, range } from './utility'
import { bcPostValidations } from './validations'

const AddBroadcastPostContainer = ({ form }) => {
  moment.tz.setDefault('Asia/Jakarta')
  const { getFieldDecorator, validateFields, setFieldsValue, getFieldsValue, setFields } = form
  const history = useHistory()
  const [, broadcastRequest] = usePost(addEditBroadcastApis.bcPostApis)
  const [recipients, getRecipients] = useGet(addEditBroadcastApis.getRecipientList)
  const [{
    POST_ACTION_ERROR,
    postActionStatus,
    postActionErrorData
  }] = useErrorContextValue()
  const [{ POST_ACTION_LOADER, RECIPIENT_LIST_LOADER }] = useLoaderContextValue()
  const editData = history.location.state
  const { resetError } = useResetError()
  const isEditMode = !!editData?.id

  const handleBroadCastAction = useCallback((actionType) => {
    validateFields((err, values) => {
      if (!err) {
        const toBeSentValues = { ...values }
        formatToBeSentValues(toBeSentValues, editData?.[IMAGE])
        if (editData?.id) {
          toBeSentValues.id = editData.id
        }
        if ([PUBLISH_NOW, UPDATE_AND_PUBLISH].includes(actionType)) {
          delete toBeSentValues[PUBLISH_DATE]
        }
        broadcastRequest(toBeSentValues, { url: apiUrls[actionType] })
      }
    })
  }, [broadcastRequest, editData, validateFields])

  useEffect(() => {
    if (POST_ACTION_ERROR && postActionErrorData?.error) {
      const { error } = postActionErrorData
      const values = getFieldsValue()
      for (const key in error) {
        setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) ? error[key].map(error => new Error(error)) : []
          }
        })
      }
    }
  }, [POST_ACTION_ERROR, postActionErrorData, setFields, getFieldsValue])

  useEffect(() => {
    if (editData) {
      setFieldsValue({
        [TITLE]: editData[TITLE],
        [CONTENT]: editData[CONTENT],
        [RECIPIENTS]: editData[RECIPIENTS]?.map(({ id }) => id),
        [PUBLISH_DATE]: editData[PUBLISH_DATE] ? moment(editData[PUBLISH_DATE]) : undefined,
        [IMAGE]: editData[IMAGE]
          ? [{
              name: 'Uploaded File',
              uid: editData[IMAGE],
              url: editData[IMAGE]
            }]
          : undefined
      })
    }
  }, [editData, setFieldsValue])

  useEffect(() => {
    getRecipients()
  }, [getRecipients])

  useEffect(() => {
    if (postActionStatus === 'success') {
      message.success('Operation Successfull')
      history.push('/employee-benefits/broadcast-center')
    }
  }, [postActionStatus, history])

  useEffect(() => {
    return () => {
      resetError([
        'postActionErrorData',
        'postActionStatus',
        'POST_ACTION_ERROR'
      ])
    }
  }, [resetError])

  useEffect(() => {
    return () => moment.tz.setDefault()
  }, [])

  return (
    <EbEmptyPage history={history} path='/employee-benefits/broadcast-center'>
      <AddBroadcastCenterStyleWrapper>
        <Spin
          spinning={!!POST_ACTION_LOADER || !!RECIPIENT_LIST_LOADER}
        >
          {(POST_ACTION_ERROR && !postActionErrorData) && <Alert type='error' message={postActionStatus} banner />}
          <Form {...horizontalLayout}>
            <Row>
              <Col span={16}>
                <Form.Item
                  label='Title'
                  labelAlign='left'
                  hasFeedback
                  required
                >
                  {
                    getFieldDecorator(TITLE, {
                      validateTrigger: ['onBlur'],
                      rules: bcPostValidations[TITLE]
                    })(
                      <Input maxLength={100} />
                    )
                  }
                </Form.Item>
                <Form.Item
                  label='Content'
                  labelAlign='left'
                  hasFeedback
                  required
                >
                  {
                    getFieldDecorator(CONTENT, {
                      rules: bcPostValidations[CONTENT]
                    })(
                      <Input.TextArea maxLength={800} rows='5' />
                    )
                  }
                </Form.Item>
                <AntdUploadFullWidthStyled>
                  <FileUploadOnGcsV2
                    form={form}
                    getFieldDecorator={getFieldDecorator}
                    identifier='broadcast'
                    name={IMAGE}
                    formItemProps={{ label: 'Upload Image', labelAlign: 'left' }}
                    buttonClassName='fluid-width'
                    maxSize={2}
                    minSize={0.001}
                    maxFileAllowed={1}
                    accept='image/png, image/jpg, image/jpeg'
                  />
                </AntdUploadFullWidthStyled>
                <Form.Item
                  label='Recipients'
                  labelAlign='left'
                >
                  {
                    getFieldDecorator(RECIPIENTS, {})(
                      <Select
                        mode='multiple'
                        filterOption={(input: any, option: any) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                      >
                        {
                          recipients?.data?.map(({ id, name }) => ({ id, name: `${id} - ${name}` })).map(({ id, name }) => (
                            <Select.Option
                              value={id}
                              key={id}
                            >
                              {name}
                            </Select.Option>
                          ))
                        }
                      </Select>
                    )
                  }
                </Form.Item>
                <Form.Item
                  label='Publish Date'
                  labelAlign='left'
                >
                  {
                    getFieldDecorator(PUBLISH_DATE, {})(
                      <DatePicker
                        showTime={{
                          defaultValue: moment().set('second', 0).set('minute', getNextMinute()),
                          minuteStep: 15,
                          format: 'HH:mm'
                        }}
                        showToday={false}
                        disabledDate={d => d.isBefore(moment(), 'day')}
                        disabledTime={(d) => ({
                          disabledHours: () => moment().hour() > 0 && d.isSame(moment(), 'day') ? range(0, moment().hour()) : [],
                          disabledMinutes: () => [...range(1, 15), ...range(16, 30), ...range(31, 45), ...range(46, 60), ...getPreviousMinutes(d)]
                        })}
                      />
                    )
                  }
                </Form.Item>
              </Col>
            </Row>
            <Row>
              <Col span={16}>
                <Form.Item {...tailFormItemLayout}>
                  <PermissionCheckerV2 requiredPermission={isEditMode ? 'ops.eb_update_broadcast' : 'ops.eb_create_broadcast'}>
                    <Button
                      htmlType='button'
                      type='primary'
                      className='mr'
                      onClick={() => handleBroadCastAction(isEditMode ? UPDATE_DRAFT : SAVE_DRAFT)}
                    >
                      Save Draft
                    </Button>
                  </PermissionCheckerV2>
                  <PermissionCheckerV2 requiredPermission={isEditMode ? 'ops.eb_update_publish_broadcast' : 'ops.eb_create_publish_broadcast'}>
                    <Button
                      htmlType='button'
                      type='primary'
                      className='mr'
                      onClick={() => handleBroadCastAction(isEditMode ? UPDATE_AND_PUBLISH : PUBLISH_NOW)}
                    >
                      Publish Now
                    </Button>
                    <Button
                      htmlType='button'
                      type='primary'
                      className='mr'
                      disabled={!form.getFieldValue(PUBLISH_DATE)}
                      onClick={() => handleBroadCastAction(isEditMode ? UPDATE_AND_SCHEDULE : SCHEDULE_PUBLISH)}
                    >
                      Publish Later
                    </Button>
                  </PermissionCheckerV2>
                </Form.Item>
              </Col>
            </Row>
          </Form>
        </Spin>
      </AddBroadcastCenterStyleWrapper>
    </EbEmptyPage>
  )
}
export default Form.create({ name: 'broadcast-post' })(AddBroadcastPostContainer)
