import moment from 'moment-timezone'
import { IMAGE, PUBLISH_DATE, TITLE } from './constants'

export function range (start, end) {
  const result = []
  for (let i = start; i < end; i++) {
    result.push(i)
  }
  return result
}

export const getPreviousMinutes = (d) => {
  const minutes = [0, 15, 30, 45]
  if (d.isAfter(moment(), 'hour')) {
    return []
  }
  return minutes.filter(m => m <= moment().minute())
}

export const getNextMinute = (d) => {
  return moment().minute() + (15 - moment().minute() % 15)
}

export const formatToBeSentValues = (toBeSentValues, existingImageUrl) => {
  toBeSentValues[IMAGE] = Array.isArray(toBeSentValues[IMAGE]) ? toBeSentValues[IMAGE][0]?.url : undefined
  toBeSentValues[PUBLISH_DATE] = toBeSentValues[PUBLISH_DATE] && toBeSentValues[PUBLISH_DATE].clone().set('second', 0).utc().unix()
  toBeSentValues[TITLE] = toBeSentValues[TITLE]?.replace(/ +(?= )/g, '')
  if (toBeSentValues[IMAGE] === existingImageUrl) {
    delete toBeSentValues[IMAGE]
  }
}
